@startuml

class Home {
  + name : string
  + address : string
}

class Department {
  + name : string
}

class Room {
  + roomNumber : string
}

class Bed {
  + bedNumber : string
  + isFree : boolean
}

class Category {
  + name : string
  + price : float
}

class Stay {
  + startDate : date
  + endDate : date
  + status : StayStatus
  + discountApplied : boolean
}

enum StayStatus {
  active
  suspended
  ended
  waiting
}

class Inhabitant {
  + name : string
  + identificationData : string
  + registrationDate : date
  + reliabilityRating : int
}

class Registration {
  + registrationDate : date
  + basicData : string
}

class Assessment {
  + needsHelpEating : boolean
  + needsHelpDressing : boolean
  + needsHelpPersonalCare : boolean
  + recommendedStayType : string
}

class Proposal {
  + proposalDate : date
  + accepted : boolean
  + isValid : boolean
}

class Invoice {
  + invoiceNumber : string
  + totalAmount : float
  + outstandingAmount : float
  + isPaid : boolean
}

class CreditNote {
  + creditNoteNumber : string
  + refundAmount : float
}

class PaymentEvent {
  + paymentDate : date
  + amountPaid : float
}

Home "1" *-- "1..*" Department
Department "1" *-- "1..*" Room
Room "1" *-- "1..*" Bed
Bed "1" -- "1" Category
Inhabitant "1" *-- "1..*" Stay
Stay "1" -- "1" Category
Inhabitant "1" -- "0..*" Registration
Registration "1" -- "0..1" Assessment
Assessment "1" -- "1" Inhabitant
Stay "1" -- "0..*" Invoice
Inhabitant "1" -- "0..*" Invoice
Proposal "1" -- "1" Inhabitant
Proposal "1" -- "1" Stay
Stay "1" -- "0..*" PaymentEvent
Invoice "1" -- "0..*" PaymentEvent
Invoice "1" -- "0..1" CreditNote

@enduml

